  const order: string[] = [];
  while (ready.length) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of dependents.get(id)!) {
      const count = remaining.get(child)! - 1;
      remaining.set(child, count);
      if (count === 0) {
        ready.push(child);
        ready.sort();
      }
    }
  }

  const earliest: Plan["earliest"] = {};
  const paths: Record<string, string[]> = {};
  const layers: string[][] = [];
  for (const id of order) {
    const task = byId.get(id)!;
    const starts = task.dependsOn.map((dependency) => earliest[dependency].finish);
    const start = starts.length ? Math.max(...starts) : 0;
    earliest[id] = { start, finish: start + task.duration };
    const layer = task.dependsOn.length ? Math.max(...task.dependsOn.map((dependency) => (paths[dependency] as unknown as { layer: number }).layer)) + 1 : 0;
